SELECT  FROM ai_scope_authorization WHERE owner_id=#{owner}
AND id > #{cursor}
ORDER BY id LIMIT #{limit}

SELECT  FROM ai_scope_authorization
WHERE owner_id=#{owner} AND purpose=#{purpose} AND scope_hash=#{scopeHash}
  AND configuration_fingerprint=#{fingerprint} AND runtime_epoch=#{epoch} AND state='ACTIVE' AND expires_at>#{now}
ORDER BY id LIMIT 50
